node -e 'const fs=require("fs");
const EMB="lib/spotlight/embeds.ts",CFG="next.config.ts",GATE="lib/spotlight/cosmetics.ts",HOLD="lib/awards/holdings.ts",SKINW="lib/profile/profile-theme-actions.ts",RAIL="components/admin/modules/personal-appearance-module.tsx",REP="app/(main)/feed/report-actions.ts",MIG="supabase/migrations/20270345002600_reports_guestbook_target.sql",REG="lib/notifications/registry.ts",GB="lib/spotlight/guestbook.ts",GBA="app/spotlight/[handle]/guestbook-actions.ts",FORM="components/spotlight/guestbook-form.tsx",WIRED="lib/notifications/wired.ts";
if(!fs.existsSync(EMB)||!fs.existsSync(GB))process.exit(79);
// Strip comment lines first, so no arm passes by reading its own documentation.
const code=(p)=>fs.existsSync(p)?fs.readFileSync(p,"utf8").split("\n").filter((l)=>!/^\s*(\/\/|\*|\/\*)/.test(l)).join("\n"):"";
const fail=(m)=>{console.error(m);process.exit(1)};
// (2) The three deferred providers: each parses, validates and builds, and its player host is in frame-src.
const emb=code(EMB),cfg=code(CFG);
for(const p of ["bandcamp","applemusic","twitch"]){if(!new RegExp("case \x27"+p+"\x27").test(emb))fail("embeds.ts no longer handles provider "+p)}
const fs2=(cfg.match(/"frame-src ([^"]+)"/)||[])[1]||"";
for(const h of ["https://bandcamp.com","https://embed.music.apple.com","https://player.twitch.tv","https://clips.twitch.tv"]){if(!fs2.split(/\s+/).includes(h))fail("next.config.ts frame-src no longer allows "+h)}
// (3) The earned gate: one pure gate + one inventory read, referenced from the skin writer and the picker (the sticker half retired, SCAN-1180).
const gate=code(GATE),hold=code(HOLD);
if(!/export function missingRequiredItems/.test(gate)||!/export function unlockedCosmetics/.test(gate))fail("lib/spotlight/cosmetics.ts no longer exports the earned gate");
if(!/export async function memberHeldItems/.test(hold)||!/store_redemptions/.test(hold))fail("lib/awards/holdings.ts no longer reads store_redemptions");
for(const [n,p] of [["the skin writer",SKINW]]){const s=code(p);if(!/missingRequiredItems\(/.test(s)||!/memberHeldItems\(/.test(s))fail(n+" ("+p+") no longer runs the earned gate over the inventory")}
if(!/unlockedCosmetics\(PROFILE_SKINS/.test(code(RAIL)))fail("the appearance rail no longer hides locked skins");
// (4) Guestbook depth: report target, unhide, sign notice through the registry.
const rep=code(REP);
if(!/VALID_TARGETS[^\n]*\x27guestbook\x27/.test(rep))fail("report-actions.ts no longer accepts a guestbook target");
if(!/target_type === \x27guestbook\x27/.test(rep)||!/spotlight_guestbook/.test(rep))fail("an actioned guestbook report no longer hides the note");
if(!fs.existsSync(MIG)||!/\x27guestbook\x27/.test(fs.readFileSync(MIG,"utf8")))fail("the reports target_type migration is gone or does not add guestbook");
if(!/export async function unhideGuestbookEntry/.test(code(GBA))||!/hidden_at: null/.test(code(GBA)))fail("the unhide action is gone");
if(!/unhideGuestbookEntry\(/.test(code(FORM))||!/targetType="guestbook"/.test(code(FORM)))fail("the guestbook controls no longer offer unhide or report");
if(!/export async function getHiddenGuestbookForOwner/.test(code(GB)))fail("the owner hidden-notes read is gone");
if(!/\x27guestbook\.sign\x27:\s*\{[\s\S]*?category: \x27comments\x27/.test(code(REG)))fail("registry.ts has no guestbook.sign row on the comments category");
if(!/notifyGuestbookSigned\(/.test(code(GBA))||!/routeNotification|\x27guestbook\.sign\x27/.test(code(GB)))fail("the sign action no longer routes the notice through the registry");
if(!/comments:\s*\[[^\]]*\x27push\x27/.test(code(WIRED)))fail("wired.ts no longer marks the comments push switch as read");
for(const t of ["lib/spotlight/embeds.test.ts","lib/spotlight/cosmetics.test.ts","lib/awards/holdings.test.ts","lib/spotlight/guestbook-notify.test.ts"]){if(!fs.existsSync(t))fail("test gone: "+t)}'
